1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30		"unicode/utf8"
31	)
32	
33	// FormatVersion is the only registry file format understood by this build.
34	const FormatVersion = 1
35	
36	// MaxQuantity is the inclusive upper bound for a batch quantity.
37	const MaxQuantity = int64(1<<63 - 1)
38	
39	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
40	
41	// Batch is the four-piece record of one supply-chain batch.
42	type Batch struct {
43		Batch    string `json:"batch"`
44		Product  string `json:"product"`
45		Quantity int64  `json:"quantity"`
46		Unit     string `json:"unit"`
47	}
48	
49	// Registry is the on-disk registry file.
50	type Registry struct {
51		Version int     `json:"version"`
52		Batches []Batch `json:"batches"`
53	}
54	
55	// Input is a normalized registration request.
56	type Input struct {
57		Batch    string
58		Product  string
59		Quantity int64
60		Unit     string
61	}
62	
63	// Outcome reports what Register did.
64	type Outcome struct {
65		Batch   Batch
66		Created bool // true when a record was added, false for an identical repeat
67	}
68	
69	// ConflictError reports that a batch id is already held by a different record.
70	// Fields lists every differing member among "product", "quantity" and "unit".
71	type ConflictError struct {
72		Batch  string
73		Fields []string
74	}
75	
76	func (e *ConflictError) Error() string {
77		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
78			e.Batch, strings.Join(e.Fields, ", "))
79	}
80	
81	// DuplicateIDError reports two stored records sharing one batch id.
82	// First and Second are the 1-based positions of the two records in the
83	// batches array when known.
84	type DuplicateIDError struct {
85		Batch  string
86		First  int
87		Second int
88	}
89	
90	func (e *DuplicateIDError) Error() string {
91		if e.First > 0 && e.Second > 0 {
92			return fmt.Sprintf("registry contains multiple records for batch %q (records %d and %d)", e.Batch, e.First, e.Second)
93		}
94		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
95	}
96	
97	// FormatError reports a structural violation of the public registry file
98	// format: a missing, duplicated, misspelled, null or mistyped field, either
99	// in the root object (Position == 0) or in one batch record (Position is its
100	// 1-based index in "batches"). Batch carries the record's batch id only when
101	// it is uniquely determined; it stays empty when the "batch" member itself
102	// is missing, duplicated or not a string.
103	type FormatError struct {
104		Position int
105		Batch    string
106		Field    string
107		Reason   string
108	}
109	
110	func (e *FormatError) Error() string {
111		where := "root object"
112		if e.Position > 0 {
113			where = fmt.Sprintf("batches record %d", e.Position)
114			if e.Batch != "" {
115				where += fmt.Sprintf(" (batch %q)", e.Batch)
116			}
117		}
118		if e.Field != "" {
119			return fmt.Sprintf("%s: field %q: %s", where, e.Field, e.Reason)
120		}
121		return fmt.Sprintf("%s: %s", where, e.Reason)
122	}
123	
124	// EncodingError reports that a text field is not valid UTF-8: either the
125	// bytes of a CLI argument, or a JSON string value whose source bytes hold
126	// malformed UTF-8 or a lone surrogate escape. The offending value is never
127	// quoted back, since decoding it would substitute U+FFFD and make distinct
128	// inputs collide. Field is one of "batch", "product" and "unit". Inside a
129	// manifest, ParseManifest wraps this in a ManifestRecordError carrying the
130	// 1-based record position.
131	type EncodingError struct {
132		Field string
133	}
134	
135	func (e *EncodingError) Error() string {
136		return fmt.Sprintf("field %q contains bytes that are not valid UTF-8; the value is rejected instead of being replaced with U+FFFD", e.Field)
137	}
138	
139	// NormalizeField trims leading and trailing whitespace; the result must stay
140	// non-empty and be valid UTF-8. Interior characters, including interior
141	// whitespace, are kept, and casing is preserved so "B1" and "b1" are
142	// different values. A genuine replacement character (U+FFFD) is ordinary
143	// text; only malformed UTF-8 bytes are refused.
144	func NormalizeField(value string) (string, error) {
145		if !utf8.ValidString(value) {
146			return "", errors.New("value is not valid UTF-8 text")
147		}
148		trimmed := strings.TrimSpace(value)
149		if trimmed == "" {
150			return "", errors.New("value must not be empty after trimming whitespace")
151		}
152		return trimmed, nil
153	}
154	
155	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
156	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
157	// compared. Zero, signs, fractions, non-ASCII digits and values above the
158	// signed 64-bit maximum are rejected.
159	func ParseQuantity(text string) (int64, error) {
160		if !quantityPattern.MatchString(text) {
161			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
162		}
163		value, err := strconv.ParseInt(text, 10, 64)
164		if err != nil {
165			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
166		}
167		if value == 0 {
168			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
169		}
170		return value, nil
171	}
172	
173	var (
174		errStringNotJSON  = errors.New("value is not a JSON string")
175		errStringEncoding = errors.New("JSON string contains bytes that are not valid UTF-8")
176	)
177	
178	// unmarshalStringStrict decodes one JSON string literal into a Go string
179	// without encoding/json's silent U+FFFD substitution. The literal must be
180	// syntactically valid JSON (only the single token, no trailing data) and the
181	// decoded text must be valid Unicode: malformed UTF-8 source bytes and lone
182	// surrogate escapes are refused, while a genuine U+FFFD — written directly
183	// or as the escape "�" — is ordinary text. Syntax problems return
184	// errStringNotJSON; encoding problems return errStringEncoding.
185	func unmarshalStringStrict(raw json.RawMessage) (string, error) {
186		token := trimJSONSpace(raw)
187		if len(token) < 2 || token[0] != '"' || token[len(token)-1] != '"' {
188			return "", errStringNotJSON
189		}
190		var b strings.Builder
191		b.Grow(len(token))
192		i := 1
193		for i < len(token)-1 {
194			c := token[i]
195			switch {
196			case c == '"':
197				// An unescaped quote before the final byte ends the literal
198				// early, so anything following it is trailing data.
199				return "", errStringNotJSON
200			case c == '\\':
201				if i+1 >= len(token)-1 {
202					return "", errStringNotJSON
203				}
204				switch token[i+1] {
205				case '"', '\\', '/':
206					b.WriteByte(token[i+1])
207					i += 2
208				case 'b':
209					b.WriteByte('\b')
210					i += 2
211				case 'f':
212					b.WriteByte('\f')
213					i += 2
214				case 'n':
215					b.WriteByte('\n')
216					i += 2
217				case 'r':
218					b.WriteByte('\r')
219					i += 2
220				case 't':
221					b.WriteByte('\t')
222					i += 2
223				case 'u':
224					r, size, err := decodeUnicodeEscape(token[i:])
225					if err != nil {
226						return "", err
227					}
228					if _, err := b.WriteRune(r); err != nil {
229						return "", errStringEncoding
230					}
231					i += size
232				default:
233					return "", errStringNotJSON
234				}
235			case c < 0x20:
236				// Raw control characters must be escaped in JSON.
237				return "", errStringNotJSON
238			default:
239				r, size := utf8.DecodeRune(token[i : len(token)-1])
240				if r == utf8.RuneError && size == 1 {
241					return "", errStringEncoding
242				}
243				b.WriteRune(r)
244				i += size
245			}
246		}
247		if i != len(token)-1 {
248			return "", errStringNotJSON
249		}
250		return b.String(), nil
251	}
252	
253	// decodeUnicodeEscape reads a "\uXXXX" escape (or a UTF-16 surrogate pair
254	// "\uHHHH\uLLLL") at the start of p, returning the rune and the number of
255	// bytes consumed. A high surrogate not followed by a low surrogate, a low
256	// surrogate with no high one, or a non-hex code unit are encoding errors.
257	func decodeUnicodeEscape(p []byte) (rune, int, error) {
258		hi, ok := hex4(p)
259		if !ok {
260			return 0, 0, errStringNotJSON
261		}
262		switch {
263		case hi >= 0xD800 && hi <= 0xDBFF:
264			if len(p) < 12 || p[6] != '\\' || p[7] != 'u' {
265				return 0, 0, errStringEncoding
266			}
267			lo, ok := hex4(p[6:])
268			if !ok {
269				return 0, 0, errStringNotJSON
270			}
271			if lo < 0xDC00 || lo > 0xDFFF {
272				return 0, 0, errStringEncoding
273			}
274			return 0x10000 + (rune(hi)-0xD800)<<10 + (rune(lo) - 0xDC00), 12, nil
275		case hi >= 0xDC00 && hi <= 0xDFFF:
276			return 0, 0, errStringEncoding
277		default:
278			return rune(hi), 6, nil
279		}
280	}
281	
282	// hex4 reads the four hex digits following a leading "\u" (p[:2] == `\u`).
283	func hex4(p []byte) (int, bool) {
284		if len(p) < 6 || p[0] != '\\' || p[1] != 'u' {
285			return 0, false
286		}
287		v := 0
288		for _, c := range p[2:6] {
289			var d byte
290			switch {
291			case c >= '0' && c <= '9':
292				d = c - '0'
293			case c >= 'a' && c <= 'f':
294				d = c - 'a' + 10
295			case c >= 'A' && c <= 'F':
296				d = c - 'A' + 10
297			default:
298				return 0, false
299			}
300			v = v<<4 | int(d)
301		}
302		return v, true
303	}
304	
305	// Load reads the registry at path. A missing file yields an empty registry
306	// with existed == false. An existing file that is empty, not parseable as
307	// the public format — including missing, null, duplicated, misspelled or
308	// mistyped fields — of an unsupported version, or holding duplicate batch
309	// ids is an error: callers must never overwrite such a file as if it were a
310	// fresh registry.
311	//
312	// A symbolic link is followed to its target, so reading through a link sees
313	// exactly the records Save writes to the linked file. A link whose target
314	// does not exist, or a chain of links forming a loop, is an error naming
315	// path and the reason — never a fresh-registry signal: treating it as a
316	// first registration would either replace the link with a regular file or
317	// create the target the user never asked for.
318	func Load(path string) (reg *Registry, existed bool, err error) {
319		data, err := os.ReadFile(path)
320		if err != nil {
321			if errors.Is(err, fs.ErrNotExist) {
322				// A dangling symbolic link also reports "not exist", but the path
323				// is occupied: the caller must not treat it as a first
324				// registration.
325				if info, lerr := os.Lstat(path); lerr == nil && info.Mode()&os.ModeSymlink != 0 {
326					return nil, true, fmt.Errorf("cannot read registry %q: symbolic link target does not exist; refusing to treat the link as a new registry", path)
327				}
328				return &Registry{Version: FormatVersion}, false, nil
329			}
330			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
331		}
332		if len(bytes.TrimSpace(data)) == 0 {
333			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
334		}
335		reg, err = decode(data)
336		if err != nil {
337			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
338		}
339		if err := validate(reg); err != nil {
340			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
341		}
342		return reg, true, nil
343	}
344	
345	// decode parses data as the public registry format. The root must be a JSON
346	// object holding exactly "version" (the integer 1) and "batches" (an array,
347	// possibly empty); every record must be an object holding exactly "batch",
348	// "product", "quantity" and "unit". Field names are matched case-sensitively
349	// after JSON string decoding, so "Version" or "Batch" are unknown fields and
350	// an escaped respelling such as "bat\u0063h" counts as the same field. A
351	// field appearing twice in one object is rejected even when both values are
352	// identical; missing fields, nulls, wrong types and unknown fields are
353	// rejected just the same. Nothing is patched up by taking the later value,
354	// merging or defaulting.
355	func decode(data []byte) (*Registry, error) {
356		dec := json.NewDecoder(bytes.NewReader(data))
357		var root json.RawMessage
358		if err := dec.Decode(&root); err != nil {
359			return nil, err
360		}
361		var extra json.RawMessage
362		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
363			if err == nil {
364				return nil, errors.New("unexpected data after registry object")
365			}
366			return nil, err
367		}
368	
369		fields, err := parseObjectFields(root)
370		if err != nil {
371			return nil, &FormatError{Reason: "root must be a JSON object holding exactly \"version\" and \"batches\""}
372		}
373		if dup, ok := duplicateField(fields); ok {
374			return nil, &FormatError{Field: dup, Reason: "field appears more than once; duplicate fields are not allowed"}
375		}
376		for _, f := range fields {
377			if f.key != "version" && f.key != "batches" {
378				return nil, &FormatError{Field: f.key, Reason: "unknown field; only \"version\" and \"batches\" are allowed"}
379			}
380		}
381		versionRaw, ok := findField(fields, "version")
382		if !ok {
383			return nil, &FormatError{Field: "version", Reason: "required field is missing"}
384		}
385		batchesRaw, ok := findField(fields, "batches")
386		if !ok {
387			return nil, &FormatError{Field: "batches", Reason: "required field is missing"}
388		}
389		version, err := parseRegistryVersion(versionRaw)
390		if err != nil {
391			return nil, err
392		}
393		if trimmed := bytes.TrimSpace(batchesRaw); len(trimmed) == 0 || trimmed[0] != '[' {
394			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
395		}
396		var elems []json.RawMessage
397		if err := json.Unmarshal(batchesRaw, &elems); err != nil {
398			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
399		}
400		reg := &Registry{Version: version, Batches: make([]Batch, 0, len(elems))}
401		for i, raw := range elems {
402			b, err := parseRegistryRecord(raw, i+1)
403			if err != nil {
404				return nil, err
405			}
406			reg.Batches = append(reg.Batches, b)
407		}
408		return reg, nil
409	}
410	
411	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
412	// Other integers report an unsupported version; anything else (strings,
413	// fractions, exponents, booleans, null, arrays, objects) is a type error.
414	func parseRegistryVersion(raw json.RawMessage) (int, error) {
415		token := string(bytes.TrimSpace(raw))
416		if isJSONInteger(token) {
417			if token == strconv.Itoa(FormatVersion) {
418				return FormatVersion, nil
419			}
420			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
421		}
422		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
423	}
424	
425	// parseRegistryRecord validates one batches element: a JSON object with
426	// exactly the four required lowercase fields, text fields as JSON strings
427	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
428	// record's 1-based position in the batches array.
429	//
430	// The structural rules (member names, strict string decoding, quantity
431	// range) are shared with parseManifestRecord; only this source's reporting
432	// differs: problems are surfaced as *FormatError with registry wording, a
433	// duplicated member anywhere in the object outranks an unknown one, and
434	// text values are read verbatim — validate handles the empty-string case.
435	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
436		var b Batch
437		fields, err := parseObjectFields(raw)
438		if err != nil {
439			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
440		}
441		// The batch id is attached to errors only when it is unambiguous:
442		// exactly one "batch" member carrying a JSON string whose decoded text
443		// is valid UTF-8. When the "batch" member itself is duplicated, or its
444		// bytes are not valid UTF-8, no id (and never a U+FFFD replacement) is
445		// picked arbitrarily.
446		batchID := unambiguousBatchID(fields, textVerbatim)
447		fail := func(field, reason string) (Batch, error) {
448			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
449		}
450	
451		switch fault := checkRecordMembers(fields, true); fault.kind {
452		case faultDuplicate:
453			return fail(fault.field, "field appears more than once; duplicate fields are not allowed")
454		case faultUnknown:
455			return fail(fault.field, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
456		}
457	
458		text := func(name string) (string, error) {
459			rawValue, ok := findField(fields, name)
460			value, problem, _ := decodeRecordText(rawValue, ok, textVerbatim)
461			switch problem {
462			case fieldMissing:
463				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
464			case fieldEncoding:
465				return "", &FormatError{Position: pos, Batch: batchID, Field: name,
466					Reason: "must be valid UTF-8 text: malformed bytes or lone surrogate escapes are rejected instead of being replaced with U+FFFD"}
467			case fieldNotString:
468				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
469			}
470			return value, nil
471		}
472		if b.Batch, err = text("batch"); err != nil {
473			return Batch{}, err
474		}
475		if b.Product, err = text("product"); err != nil {
476			return Batch{}, err
477		}
478		if b.Unit, err = text("unit"); err != nil {
479			return Batch{}, err
480		}
481		quantityRaw, ok := findField(fields, "quantity")
482		if !ok {
483			return fail("quantity", "required field is missing")
484		}
485		b.Quantity, err = registryQuantityError(bytes.TrimSpace(quantityRaw))
486		if err != nil {
487			return fail("quantity", err.Error())
488		}
489		return b, nil
490	}
491	
492	// isJSONInteger reports whether token is a JSON number literal without
493	// fraction or exponent. The token comes from validated JSON, so leading
494	// zeros cannot hide extra digits.
495	func isJSONInteger(token string) bool {
496		if token == "" {
497			return false
498		}
499		if token[0] == '-' {
500			token = token[1:]
501		}
502		if token == "" {
503			return false
504		}
505		for i := 0; i < len(token); i++ {
506			if token[i] < '0' || token[i] > '9' {
507				return false
508			}
509		}
510		return true
511	}
512	
513	// objectField is one member of a JSON object in source order; the key is
514	// the decoded JSON string, so escaped spellings compare by meaning.
515	type objectField struct {
516		key   string
517		value json.RawMessage
518	}
519	
520	// parseObjectFields decodes a single JSON object value into its members in
521	// source order, keeping duplicates visible for the caller to reject. Keys
522	// are re-scanned strictly: encoding/json would otherwise hand back U+FFFD
523	// substitutions for malformed key bytes.
524	func parseObjectFields(raw []byte) ([]objectField, error) {
525		trimmed := bytes.TrimSpace(raw)
526		if len(trimmed) == 0 || trimmed[0] != '{' {
527			return nil, errors.New("value is not a JSON object")
528		}
529		dec := json.NewDecoder(bytes.NewReader(trimmed))
530		if _, err := dec.Token(); err != nil { // opening brace
531			return nil, err
532		}
533		var fields []objectField
534		for dec.More() {
535			keyStart := dec.InputOffset()
536			tok, err := dec.Token()
537			keyEnd := dec.InputOffset()
538			if err != nil {
539				return nil, err
540			}
541			key, ok := tok.(string)
542			if !ok {
543				return nil, errors.New("object keys must be JSON strings")
544			}
545			if _, err := unmarshalStringStrict(keyTokenBytes(trimmed, int(keyStart), int(keyEnd))); err != nil {
546				if errors.Is(err, errStringEncoding) {
547					return nil, errors.New("object key contains bytes that are not valid UTF-8")
548				}
549				return nil, err
550			}
551			var value json.RawMessage
552			if err := dec.Decode(&value); err != nil {
553				return nil, err
554			}
555			fields = append(fields, objectField{key: key, value: value})
556		}
557		if _, err := dec.Token(); err != nil { // closing brace
558			return nil, err
559		}
560		return fields, nil
561	}
562	
563	// trimJSONSpace strips only the four JSON whitespace bytes (space, tab,
564	// carriage return, newline). bytes.TrimSpace would also remove U+000B and
565	// other Unicode whitespace, which is illegal around a JSON token and must
566	// therefore be rejected rather than ignored.
567	func trimJSONSpace(b []byte) []byte {
568		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' }
569		for len(b) > 0 && isSpace(b[0]) {
570			b = b[1:]
571		}
572		for len(b) > 0 && isSpace(b[len(b)-1]) {
573			b = b[:len(b)-1]
574		}
575		return b
576	}
577	
578	// keyTokenBytes isolates one key token inside trimmed[start:end]. The
579	// decoder reports the offset just after the preceding token (so the span
580	// may still contain a separating comma and whitespace), hence the left trim.
581	func keyTokenBytes(trimmed []byte, start, end int) []byte {
582		return bytes.TrimLeft(trimmed[start:end], " \t\r\n,")
583	}
584	
585	// duplicateField returns the first field name appearing more than once.
586	func duplicateField(fields []objectField) (string, bool) {
587		seen := make(map[string]struct{}, len(fields))
588		for _, f := range fields {
589			if _, dup := seen[f.key]; dup {
590				return f.key, true
591			}
592			seen[f.key] = struct{}{}
593		}
594		return "", false
595	}
596	
597	// findField returns the raw value of the first member named name.
598	func findField(fields []objectField, name string) (json.RawMessage, bool) {
599		for _, f := range fields {
600			if f.key == name {
601				return f.value, true
602			}
603		}
604		return nil, false
605	}
606	
607	// countField counts the members named name.
608	func countField(fields []objectField, name string) int {
609		n := 0
610		for _, f := range fields {
611			if f.key == name {
612				n++
613			}
614		}
615		return n
616	}
