618	func validate(reg *Registry) error {
619		seen := make(map[string]int, len(reg.Batches))
620		for i, b := range reg.Batches {
621			pos := i + 1
622			if b.Batch == "" || b.Product == "" || b.Unit == "" {
623				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
624			}
625			if b.Quantity <= 0 {
626				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
627			}
628			if first, dup := seen[b.Batch]; dup {
629				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
630			}
631			seen[b.Batch] = pos
632		}
633		return nil
634	}
