636	// ManifestRecordError reports a manifest record that is structurally invalid
637	// or carries a quantity outside the accepted range. Position is the record's
638	// 1-based position in the manifest.
639	type ManifestRecordError struct {
640		Position int
641		Batch    string // normalized batch id when available, otherwise ""
642		Reason   string
643	}
644	
645	func (e *ManifestRecordError) Error() string {
646		if e.Batch != "" {
647			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
648		}
649		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
650	}
