652	// ManifestConflictError reports that a manifest record disagrees with the
653	// record already registered, or introduced earlier in the same manifest,
654	// under the same batch id. Position is the record's 1-based position in the
655	// manifest and Fields lists every differing member among "product",
656	// "quantity" and "unit" in that order.
657	type ManifestConflictError struct {
658		Position int
659		Batch    string
660		Fields   []string
661		Source   string // "registry" or "manifest"
662		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
663	}
664	
665	func (e *ManifestConflictError) Error() string {
666		if e.Source == "manifest" {
667			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
668				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
669		}
670		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
671			e.Position, e.Batch, strings.Join(e.Fields, ", "))
672	}
