674	// ParseManifest decodes data as a non-empty JSON array holding exactly the
675	// four required fields batch, product, quantity and unit per element. The
676	// three text fields must be JSON strings that are not blank after trimming;
677	// quantity must be a JSON integer (no strings, fractions or exponents) in
678	// the range 1..MaxQuantity. An empty file, empty array, non-array document
679	// or any malformed record is rejected. The manifest bytes are never written.
680	func ParseManifest(data []byte) ([]Input, error) {
681		trimmed := bytes.TrimSpace(data)
682		if len(trimmed) == 0 {
683			return nil, errors.New("manifest file is empty")
684		}
685		if trimmed[0] != '[' {
686			return nil, errors.New("manifest must be a non-empty JSON array of records")
687		}
688	
689		var elems []json.RawMessage
690		dec := json.NewDecoder(bytes.NewReader(data))
691		if err := dec.Decode(&elems); err != nil {
692			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
693		}
694		var extra json.RawMessage
695		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
696			if err == nil {
697				return nil, errors.New("manifest has unexpected data after the array")
698			}
699			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
700		}
701		if len(elems) == 0 {
702			return nil, errors.New("manifest must contain at least one record")
703		}
704	
705		inputs := make([]Input, 0, len(elems))
706		for i, raw := range elems {
707			pos := i + 1
708			in, err := parseManifestRecord(raw)
709			if err != nil {
710				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
711			}
712			inputs = append(inputs, in)
713		}
714		return inputs, nil
715	}
716	
717	// batchRecordFields are the only members a batch record may carry, in the
718	// registry file and in an import manifest alike.
719	var batchRecordFields = map[string]struct{}{
720		"batch": {}, "product": {}, "quantity": {}, "unit": {},
721	}
722	
723	// parseManifestRecord validates one manifest element: it must be a JSON
724	// object with exactly the four required keys, text fields as non-blank,
725	// valid UTF-8 strings and quantity as a strict JSON integer. The members
726	// are scanned with parseObjectFields (strict key decoding, duplicates kept
727	// visible) rather than a lenient map unmarshal, so malformed key or value
728	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
729	// fail — an unknown, duplicated or case-mismatched field included — the
730	// returned Input carries the normalized batch id whenever exactly one
731	// "batch" member holds valid, non-blank text, so the caller can name the
732	// batch in the error; otherwise it stays empty.
733	//
734	// The structural rules are shared with parseRegistryRecord; this source's
735	// own choices are: member-name anomalies are reported in source order
736	// (unknown and duplicate carry equal weight), text is trimmed and must stay
737	// non-empty, and reasons use manifest wording (including *EncodingError for
738	// malformed text).
739	func parseManifestRecord(raw json.RawMessage) (Input, error) {
740		var in Input
741		members, err := parseObjectFields(raw)
742		if err != nil {
743			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
744		}
745		// Attach the batch id to whatever error this record raises, but only when
746		// it is unambiguous: exactly one "batch" member (compared after JSON key
747		// decoding, so an escaped respelling counts as the same field) carrying a
748		// JSON string whose decoded text is valid UTF-8 and non-blank once
749		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
750		// member leaves the id out — never a U+FFFD substitution, and never one
751		// of two duplicate values picked arbitrarily, even when both are equal.
752		// Where the "batch" member sits relative to the offending field does not
753		// matter.
754		in.Batch = unambiguousBatchID(members, textTrimmed)
755	
756		// Manifest member-name problems are reported in source order: the first
757		// unknown name or first repeat fails the record.
758		switch fault := checkRecordMembers(members, false); fault.kind {
759		case faultUnknown:
760			return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", fault.field)
761		case faultDuplicate:
762			return in, fmt.Errorf("record lists field %q more than once", fault.field)
763		}
764	
765		textField := func(name string) (string, error) {
766			rawValue, found := findField(members, name)
767			value, problem, cause := decodeRecordText(rawValue, found, textTrimmed)
768			switch problem {
769			case fieldMissing:
770				return "", fmt.Errorf("missing required field %q", name)
771			case fieldNotString:
772				return "", fmt.Errorf("field %q must be a JSON string", name)
773			case fieldEncoding:
774				return "", &EncodingError{Field: name}
775			case fieldBlank:
776				return "", fmt.Errorf("field %q must not be blank: %w", name, cause)
777			}
778			return value, nil
779		}
780	
781		in.Batch, err = textField("batch")
782		if err != nil {
783			return in, err
784		}
785		in.Product, err = textField("product")
786		if err != nil {
787			return in, err
788		}
789		in.Unit, err = textField("unit")
790		if err != nil {
791			return in, err
792		}
793		quantityRaw, ok := findField(members, "quantity")
794		if !ok {
795			return in, errors.New("missing required field \"quantity\"")
796		}
797		in.Quantity, err = manifestQuantityError(bytes.TrimSpace(quantityRaw))
798		if err != nil {
799			return in, err
800		}
801		return in, nil
802	}
803	
804	// ImportResult is one entry of an Import outcome: the normalized record in
805	// manifest order plus whether it was newly created or already present.
806	type ImportResult struct {
807		Batch   Batch
808		Created bool
809	}
810	
811	// validateManifestInput applies the same effective-value rules to one
812	// directly submitted record that Register enforces for single entries and
813	// parseManifestRecord enforces for file records: the three text fields must
814	// be valid UTF-8 and must not be empty strings, and quantity must lie in
815	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
816	// whitespace trimming or case folding (the command-line entry normalizes
817	// before constructing the Input), so whitespace-only text is accepted as
818	// ordinary non-empty text. pos is the record's 1-based position in this
819	// submission. The returned *ManifestRecordError names the offending field
820	// in its reason and cites the batch id only when that id is itself
821	// non-empty, valid UTF-8 text; it is never invented or substituted when the
822	// batch field is empty or malformed.
823	func validateManifestInput(in Input, pos int) error {
824		// batchID is "" whenever the batch field itself is empty or malformed, so
825		// it is safe to attach it to whichever error follows.
826		batchID := safeBatchIDForError(in.Batch)
827		// Import reports an encoding problem anywhere in the three text fields
828		// before any empty-text problem; quantity problems come after both.
829		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
830		if issue, bad := firstTextIssue(issues, textEncoding); bad {
831			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: issue.field}).Error()}
832		}
833		if issue, bad := firstTextIssue(issues, textEmpty); bad {
834			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", issue.field)}
835		}
836		switch classifyDecodedQuantity(in.Quantity) {
837		case decodedQtyNotPositive:
838			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
839		case decodedQtyAboveMax:
840			return &ManifestRecordError{Position: pos, Batch: batchID,
841				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
842		}
843		return nil
844	}
845	
846	// Import validates every record of inputs before appending anything: the
847	// whole manifest fails if any record carries invalid UTF-8, an empty text
848	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
849	// already stored or seen earlier in this submission — or if any record
850	// conflicts with a stored record or with an earlier manifest record, and reg
851	// is left untouched on error. Directly submitted text is kept verbatim. New
852	// batch ids are appended in first-occurrence order; an id already stored or
853	// introduced earlier in the same manifest is confirmed as a duplicate only
854	// when product, quantity and unit all match. Results come back in manifest
855	// order; Created is false for duplicates.
856	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
857		if reg.Version != FormatVersion {
858			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
859		}
860		if len(inputs) == 0 {
861			return nil, errors.New("manifest must contain at least one record")
862		}
863		// Reject malformed text and non-effective values before touching
864		// anything; this covers records handed in directly by Go callers the
865		// same way ParseManifest covers file records, so a blank text field or a
866		// non-positive quantity can never reach the new/duplicate/conflict logic
867		// below and end up in a file the reader would refuse. Text is checked
868		// verbatim: direct submissions get no trimming or case folding (only the
869		// command-line entry normalizes, before building the Input).
870		for i, in := range inputs {
871			if err := validateManifestInput(in, i+1); err != nil {
872				return nil, err
873			}
874		}
875	
876		// Work on a copy: a rejected manifest must never partially land in reg.
877		working := append([]Batch(nil), reg.Batches...)
878		indexByID := make(map[string]int, len(working))
879		for i, b := range working {
880			indexByID[b.Batch] = i
881		}
882		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
883	
884		out := make([]ImportResult, len(inputs))
885		for i, in := range inputs {
886			pos := i + 1
887			if idx, known := indexByID[in.Batch]; known {
888				existing := working[idx]
889				diffs := diffFields(existing, in)
890				if len(diffs) > 0 {
891					if prev, inManifest := firstPos[in.Batch]; inManifest {
892						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
893					}
894					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
895				}
896				out[i] = ImportResult{Batch: existing, Created: false}
897				continue
898			}
899			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
900			working = append(working, b)
901			indexByID[in.Batch] = len(working) - 1
902			firstPos[in.Batch] = pos
903			out[i] = ImportResult{Batch: b, Created: true}
904		}
905	
906		reg.Batches = working
907		return out, nil
908	}
909	
910	// diffFields lists the members of product, quantity and unit in which in
911	// differs from existing, in that fixed order.
912	func diffFields(existing Batch, in Input) []string {
913		var diffs []string
914		if existing.Product != in.Product {
915			diffs = append(diffs, "product")
916		}
917		if existing.Quantity != in.Quantity {
918			diffs = append(diffs, "quantity")
919		}
920		if existing.Unit != in.Unit {
921			diffs = append(diffs, "unit")
922		}
923		return diffs
924	}
925	
926	// Register adds in to reg, or confirms the identical record already stored
927	// under the same batch id. A batch id held by a record differing in product,
928	// quantity or unit produces a *ConflictError and leaves reg untouched. The
929	// zero Outcome is returned together with the error.
930	func Register(reg *Registry, in Input) (Outcome, error) {
931		if reg.Version != FormatVersion {
932			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
933		}
934		// Register reports any empty text field before any encoding problem;
935		// quantity problems come after both.
936		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
937		if _, bad := firstTextIssue(issues, textEmpty); bad {
938			return Outcome{}, errors.New("batch, product and unit must be non-empty")
939		}
940		if issue, bad := firstTextIssue(issues, textEncoding); bad {
941			return Outcome{}, &EncodingError{Field: issue.field}
942		}
943		if !quantityInRange(in.Quantity) {
944			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
945		}
946		for _, b := range reg.Batches {
947			if b.Batch != in.Batch {
948				continue
949			}
950			if diffs := diffFields(b, in); len(diffs) > 0 {
951				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
952			}
953			return Outcome{Batch: b, Created: false}, nil
954		}
955		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
956		reg.Batches = append(reg.Batches, b)
957		return Outcome{Batch: b, Created: true}, nil
958	}
959	
960	// validateForSave checks every record of reg against the rules Load enforces,
961	// so a hand-assembled registry cannot be persisted in a shape the reader
962	// would refuse. Records are checked in order and the first violation is
963	// reported as a *FormatError naming the 1-based record position, the field
964	// and the reason; the batch id is attached only when it is itself non-empty,
965	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
966	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
967	// positions, even when the two records are identical: Save persists records,
968	// it never confirms duplicates or merges them. Text is checked verbatim —
969	// no trimming, no case folding — and reg is never modified.
970	func validateForSave(reg *Registry) error {
971		seen := make(map[string]int, len(reg.Batches))
972		for i, b := range reg.Batches {
973			pos := i + 1
974			batchID := safeBatchIDForError(b.Batch)
975			// Save reports the first problem in batch, product, unit field
976			// order, with a field's encoding problem ahead of its empty-string
977			// problem — exactly the order inspectRecordText lists issues in.
978			if issues := inspectRecordText(b.Batch, b.Product, b.Unit); len(issues) > 0 {
979				issue := issues[0]
980				if issue.kind == textEncoding {
981					return &FormatError{Position: pos, Batch: batchID, Field: issue.field,
982						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
983				}
984				return &FormatError{Position: pos, Batch: batchID, Field: issue.field, Reason: "must not be empty"}
985			}
986			if !quantityInRange(b.Quantity) {
987				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
988					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
989			}
990			if first, dup := seen[b.Batch]; dup {
991				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
992			}
993			seen[b.Batch] = pos
994		}
995		return nil
996	}
