998	// WriteTempContent and RenameTempFile are the two failure-prone steps of the
999	// atomic save — writing the new content into the temporary file, and replacing
1000	// the target with it — kept behind package-level variables so the regression
1001	// tests (including the batch-import entry-point tests in the cmd/govflow
1002	// package) can make a chosen step of a real save fail deterministically, on the
1003	// save's actual target rather than a neighboring unusable path. Production
1004	// behavior is exactly the wrapped os operations; production code never swaps
1005	// them.
1006	var (
1007		WriteTempContent = func(f *os.File, data []byte) (int, error) { return f.Write(data) }
1008		RenameTempFile   = os.Rename
1009	)
1010	
1011	// resolveRegistryTarget returns the file a save to path must actually
1012	// replace. When path is a symbolic link, the link is followed to its target
1013	// — an absolute target, or a relative one resolved against the link's own
1014	// directory, never against the process working directory — so the save
1015	// updates the file the user sees through the link instead of replacing the
1016	// link with a regular file. A dangling link or a link loop is an error: the
1017	// save must not create the target or overwrite the link as if this were a
1018	// first registration. A non-link path (existing or not) is returned
1019	// unchanged.
1020	func resolveRegistryTarget(path string) (string, error) {
1021		info, err := os.Lstat(path)
1022		if err != nil {
1023			if errors.Is(err, fs.ErrNotExist) {
1024				return path, nil
1025			}
1026			return "", fmt.Errorf("cannot inspect registry path: %w", err)
1027		}
1028		if info.Mode()&os.ModeSymlink == 0 {
1029			return path, nil
1030		}
1031		target, err := filepath.EvalSymlinks(path)
1032		if err != nil {
1033			return "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", err)
1034		}
1035		return target, nil
1036	}
1037	
1038	// Save atomically writes reg to path, replacing the file only after the new
1039	// content is fully on disk so an existing registry stays usable on failure.
1040	// Records are serialized in their current order; the file is created with
1041	// 0644 permissions or, when replacing an existing file, with its permissions.
1042	//
1043	// When path is a symbolic link, the link's target is the file replaced: the
1044	// new content is prepared next to the target and moved over it, so the link
1045	// stays a link to the same target and the target keeps its permissions,
1046	// while reads through either the link or the real path see the saved
1047	// records. A link whose target does not exist, or a link loop, rejects the
1048	// save with an error naming path — the target is never created and the link
1049	// is never replaced.
1050	//
1051	// Every record must satisfy the same effective-value rules Load enforces, so
1052	// a registry saved successfully always reads back: batch, product and unit
1053	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
1054	// folding, so whitespace-only text is ordinary non-empty text), quantity
1055	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
1056	// byte-for-byte comparison, two identical records included. Any violation
1057	// rejects the whole save before anything is written: an existing target
1058	// keeps its bytes and modification time, a missing target stays missing and
1059	// no temporary file is left behind. A nil or empty Batches is a legal empty
1060	// registry and is written as "batches": [] without touching reg itself.
1061	func Save(path string, reg *Registry) error {
1062		if reg.Version != FormatVersion {
1063			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1064		}
1065		if err := validateForSave(reg); err != nil {
1066			return fmt.Errorf("cannot save registry %q: %w", path, err)
1067		}
1068		target, err := resolveRegistryTarget(path)
1069		if err != nil {
1070			return fmt.Errorf("cannot save registry %q: %w", path, err)
1071		}
1072		mode := os.FileMode(0o644)
1073		if info, err := os.Stat(target); err == nil {
1074			mode = info.Mode().Perm()
1075		} else if !errors.Is(err, fs.ErrNotExist) {
1076			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1077		}
1078	
1079		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
1080			return fmt.Errorf("cannot save registry %q: %w", path, err)
1081		}
1082	
1083		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1084		// read back) without mutating the caller's registry.
1085		out := *reg
1086		if out.Batches == nil {
1087			out.Batches = []Batch{}
1088		}
1089		var buf bytes.Buffer
1090		enc := json.NewEncoder(&buf)
1091		enc.SetEscapeHTML(false)
1092		enc.SetIndent("", "  ")
1093		if err := enc.Encode(&out); err != nil {
1094			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1095		}
1096	
1097		tmp, err := os.CreateTemp(filepath.Dir(target), ".govflow-registry-*.tmp")
1098		if err != nil {
1099			return fmt.Errorf("cannot save registry %q: %w", path, err)
1100		}
1101		tmpName := tmp.Name()
1102		abort := func(cause error) error {
1103			tmp.Close()
1104			os.Remove(tmpName)
1105			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1106		}
1107		if _, err := WriteTempContent(tmp, buf.Bytes()); err != nil {
1108			return abort(err)
1109		}
1110		if err := tmp.Chmod(mode); err != nil {
1111			return abort(err)
1112		}
1113		if err := tmp.Sync(); err != nil {
1114			return abort(err)
1115		}
1116		if err := tmp.Close(); err != nil {
1117			os.Remove(tmpName)
1118			return fmt.Errorf("cannot save registry %q: %w", path, err)
1119		}
1120		if err := RenameTempFile(tmpName, target); err != nil {
1121			os.Remove(tmpName)
1122			return fmt.Errorf("cannot save registry %q: %w", path, err)
1123		}
1124		return nil
1125	}
