35	
36	type usageError struct {
37		msg   string
38		usage string
39	}
40	
41	func (e *usageError) Error() string { return e.msg }
42	
43	func run(args []string) error {
44		command := "demo"
45		if len(args) > 0 {
46			command = args[0]
47		}
48		switch command {
49		case "demo":
50			runDemo()
51			return nil
52		case "version":
53			fmt.Println("govflow 0.1.0")
54			return nil
55		case "help", "-h", "--help":
56			fmt.Print(rootUsage())
57			return nil
