164	func runBatchRegister(args []string, stdout io.Writer) error {
165		fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
166		fs.SetOutput(io.Discard)
167		registryPath := fs.String("registry", "", "registry `file` to read and write")
168		batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
169		productRaw := fs.String("product", "", "product number")
170		quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
171		unitRaw := fs.String("unit", "", "measurement unit")
172		if err := fs.Parse(args); err != nil {
173			if errors.Is(err, flag.ErrHelp) {
174				fmt.Fprint(stdout, rootUsage())
175				return nil
176			}
177			return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
178		}
179		if fs.NArg() != 0 {
180			return &usageError{
181				msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
182				usage: batchRegisterUsage,
183			}
184		}
185	
186		// Missing or malformed input must never create or modify the registry
187		// file, so required flags are checked before reading or writing anything.
188		required := []struct {
189			name  string
190			value string
191		}{
192			{"--registry", *registryPath},
193			{"--batch", *batchRaw},
194			{"--product", *productRaw},
195			{"--quantity", *quantityRaw},
196			{"--unit", *unitRaw},
197		}
198		var missing []string
199		for _, f := range required {
200			if f.value == "" {
201				missing = append(missing, f.name)
202			}
203		}
204		if len(missing) > 0 {
205			return &usageError{
206				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
207				usage: batchRegisterUsage,
208			}
209		}
210	
211		batch, err := batchreg.NormalizeField(*batchRaw)
212		if err != nil {
213			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
214		}
215		product, err := batchreg.NormalizeField(*productRaw)
216		if err != nil {
217			return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
218		}
219		unit, err := batchreg.NormalizeField(*unitRaw)
220		if err != nil {
221			return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
222		}
223		quantity, err := batchreg.ParseQuantity(*quantityRaw)
224		if err != nil {
225			return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
226		}
227	
228		reg, existed, err := batchreg.Load(*registryPath)
229		if err != nil {
230			return err
231		}
232		outcome, err := batchreg.Register(reg, batchreg.Input{
233			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
234		})
235		if err != nil {
236			return err
237		}
238		if outcome.Created {
239			if err := batchreg.Save(*registryPath, reg); err != nil {
240				if !existed {
241					// Nothing was registered before; drop any partial new file.
242					removePartialNewRegistry(*registryPath)
243				}
244				return err
245			}
246		}
247	
248		status := "duplicate"
249		if outcome.Created {
250			status = "created"
251		}
252		result := struct {
253			Batch    string `json:"batch"`
254			Product  string `json:"product"`
255			Quantity int64  `json:"quantity"`
256			Unit     string `json:"unit"`
257			Status   string `json:"status"`
258		}{
259			Batch:    outcome.Batch.Batch,
260			Product:  outcome.Batch.Product,
261			Quantity: outcome.Batch.Quantity,
262			Unit:     outcome.Batch.Unit,
263			Status:   status,
264		}
265		payload, err := json.Marshal(result)
266		if err != nil {
267			return err
268		}
269		_, err = fmt.Fprintln(stdout, string(payload))
270		return err
271	}
272	
273	func runBatchImport(args []string, stdout io.Writer) error {
274		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
275		fs.SetOutput(io.Discard)
276		registryPath := fs.String("registry", "", "registry `file` to read and write")
277		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
278		if err := fs.Parse(args); err != nil {
279			if errors.Is(err, flag.ErrHelp) {
280				fmt.Fprint(stdout, rootUsage())
281				return nil
282			}
283			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
284		}
285		if fs.NArg() != 0 {
286			return &usageError{
287				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
288				usage: batchImportUsage,
289			}
290		}
291		if *registryPath == "" || *inputPath == "" {
292			var missing []string
293			if *registryPath == "" {
294				missing = append(missing, "--registry")
295			}
296			if *inputPath == "" {
297				missing = append(missing, "--input")
298			}
299			return &usageError{
300				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
301				usage: batchImportUsage,
302			}
303		}
304	
305		// The manifest is read-only and is parsed (and fully validated) before
306		// the registry is loaded or written, so bad input cannot touch it.
307		data, err := os.ReadFile(*inputPath)
308		if err != nil {
309			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
310		}
311		inputs, err := batchreg.ParseManifest(data)
312		if err != nil {
313			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
314		}
315	
316		reg, existed, err := batchreg.Load(*registryPath)
317		if err != nil {
318			return fmt.Errorf("batch-import: %w", err)
319		}
320		outcomes, err := batchreg.Import(reg, inputs)
321		if err != nil {
322			return fmt.Errorf("batch-import: %w", err)
323		}
324	
325		type importResultJSON struct {
326			Batch    string `json:"batch"`
327			Product  string `json:"product"`
328			Quantity int64  `json:"quantity"`
329			Unit     string `json:"unit"`
330			Status   string `json:"status"`
331		}
332		results := make([]importResultJSON, len(outcomes))
333		anyCreated := false
334		for i, o := range outcomes {
335			status := "duplicate"
336			if o.Created {
337				status = "created"
338				anyCreated = true
339			}
340			results[i] = importResultJSON{
341				Batch:    o.Batch.Batch,
342				Product:  o.Batch.Product,
343				Quantity: o.Batch.Quantity,
344				Unit:     o.Batch.Unit,
345				Status:   status,
346			}
347		}
348	
349		// An all-duplicate manifest must leave bytes and mtime untouched, so the
350		// registry is written only when at least one record was newly created.
351		if anyCreated {
352			if err := batchreg.Save(*registryPath, reg); err != nil {
353				if !existed {
354					// The registry never existed before this import; drop any
355					// partial new file so a failed save leaves nothing behind.
356					removePartialNewRegistry(*registryPath)
357				}
358				return fmt.Errorf("batch-import: %w", err)
359			}
360		}
361	
362		payload, err := json.Marshal(struct {
363			Results []importResultJSON `json:"results"`
364		}{Results: results})
365		if err != nil {
366			return fmt.Errorf("batch-import: %w", err)
367		}
368		_, err = fmt.Fprintln(stdout, string(payload))
369		if err != nil {
370			return fmt.Errorf("batch-import: %w", err)
371		}
372		return nil
373	}
374	
375	// removePartialNewRegistry drops a partially written new registry file after
376	// a failed first save. A symbolic link is never removed: the link is the
377	// user's pointer to the real registry file, not a partial creation of this
378	// run.
379	func removePartialNewRegistry(path string) {
380		info, err := os.Lstat(path)
381		if err != nil || info.Mode()&os.ModeSymlink != 0 {
382			return
383		}
384		os.Remove(path)
385	}
386	
387	func runDemo() {
388		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
389			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
390		if err := govflow.Vote(&proposal, 700, true); err != nil {
391			fmt.Println("vote refused:", err)
392		}
393		if err := govflow.Vote(&proposal, 200, false); err != nil {
394			fmt.Println("vote refused:", err)
395		}
396		next := govflow.Tally(&proposal)
397		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
398		proposal.State = next
399		proposal.TimelockEnd = 400
400		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
401	}
